/* Cartes d'exemple de Fiches mémo par niveau, générées par scripts/flashcards/build.py --emettre
   depuis scripts/flashcards/lot*.py (sources et contrôles dans ces fichiers) — ne pas modifier ici. */
window.PARAPHE_CARTES = [{"id":"seed-fc-l1-entree-vigueur","niveau":"L1","matiere":"Introduction au droit","recto":"Quand une loi publiée au Journal officiel entre-t-elle en vigueur ?","verso":"À la date qu'elle fixe ou, à défaut, le lendemain de sa publication. Les dispositions qui exigent des mesures d'application n'entrent en vigueur qu'avec ces mesures (art. 1er C. civ.).","source":"Code civil, art. 1er"},{"id":"seed-fc-l1-non-retroactivite","niveau":"L1","matiere":"Introduction au droit","recto":"La loi ne dispose que pour l'{{avenir}} ; elle n'a point d'effet {{rétroactif}}.","verso":"Art. 2 du Code civil : le principe de non-rétroactivité de la loi.","type":"trous","source":"Code civil, art. 2"},{"id":"seed-fc-l1-deni-justice","niveau":"L1","matiere":"Introduction au droit","recto":"Un juge peut-il refuser de trancher un litige parce que la loi est muette ou obscure ?","verso":"Non : il commettrait un déni de justice (art. 4 C. civ.). Il doit interpréter la loi et trancher.","source":"Code civil, art. 4"},{"id":"seed-fc-l1-arrets-reglement","niveau":"L1","matiere":"Introduction au droit","recto":"Que signifie l'interdiction des « arrêts de règlement » ?","verso":"Le juge ne peut pas statuer par voie de disposition générale et réglementaire : sa décision ne vaut que pour l'affaire qu'il juge (art. 5 C. civ.).","source":"Code civil, art. 5"},{"id":"seed-fc-l1-ordre-public","niveau":"L1","matiere":"Introduction au droit","recto":"On ne peut déroger, par des conventions particulières, aux lois qui intéressent l'{{ordre public}} et les {{bonnes mœurs}}.","verso":"Art. 6 du Code civil.","type":"trous","source":"Code civil, art. 6"},{"id":"seed-fc-l1-traites-lois","niveau":"L1-L2","matiere":"Introduction au droit","recto":"Quelle autorité ont les traités régulièrement ratifiés par rapport aux lois ?","verso":"Une autorité supérieure à celle des lois, dès leur publication, sous réserve de leur application par l'autre partie (art. 55 de la Constitution). Le juge judiciaire en a tiré les conséquences avec l'arrêt Jacques Vabre (1975), le Conseil d'État avec l'arrêt Nicolo (1989).","source":"Constitution, art. 55 ; fiches d'arrêt Jacques Vabre et Nicolo","arrets":["seed-jp-1975-05-24-societe-des-cafes-jacques-vabre-ch-mixte","seed-jp-1989-10-20-nicolo-ass"]},{"id":"seed-fc-l1-vie-privee","niveau":"L1","matiere":"Introduction au droit","recto":"Chacun a droit au respect de sa {{vie privée}}.","verso":"Art. 9 du Code civil ; le juge peut ordonner toute mesure pour faire cesser une atteinte à l'intimité de la vie privée.","type":"trous","source":"Code civil, art. 9"},{"id":"seed-fc-l1-corps-humain","niveau":"L1","matiere":"Introduction au droit","recto":"Chacun a droit au respect de son corps. Le corps humain est {{inviolable}}. Le corps humain, ses éléments et ses produits ne peuvent faire l'objet d'un {{droit patrimonial}}.","verso":"Art. 16-1 du Code civil.","type":"trous","source":"Code civil, art. 16-1"},{"id":"seed-fc-l1-infans-conceptus","niveau":"L1","matiere":"Introduction au droit","recto":"Un enfant simplement conçu au décès de son père peut-il hériter de lui ?","verso":"Oui, s'il naît viable : pour succéder, il faut exister à l'ouverture de la succession ou, ayant déjà été conçu, naître viable (art. 725 C. civ.). C'est une application de l'adage « infans conceptus ».","source":"Code civil, art. 725"},{"id":"seed-fc-l1-majorite","niveau":"L1","matiere":"Introduction au droit","recto":"La majorité est fixée à {{dix-huit ans}} accomplis ; à cet âge, chacun est {{capable}} d'exercer les droits dont il a la jouissance.","verso":"Art. 414 du Code civil.","type":"trous","source":"Code civil, art. 414"},{"id":"seed-fc-l1-curatelle-tutelle","niveau":"L1","matiere":"Introduction au droit","recto":"Curatelle ou tutelle : quelle différence ?","verso":"En curatelle, la personne agit elle-même mais doit être assistée ou contrôlée dans les actes importants ; en tutelle, elle est représentée de manière continue. Chacune n'est prononcée que si une mesure plus légère (sauvegarde de justice, puis curatelle) ne suffit pas (art. 440 C. civ.).","source":"Code civil, art. 440"},{"id":"seed-fc-l1-domicile","niveau":"L1","matiere":"Introduction au droit","recto":"Où se trouve le domicile d'une personne, au sens du Code civil ?","verso":"Au lieu où elle a son principal établissement (art. 102 C. civ.).","source":"Code civil, art. 102"},{"id":"seed-fc-l1-republique","niveau":"L1","matiere":"Droit constitutionnel","recto":"La France est une République {{indivisible}}, {{laïque}}, {{démocratique}} et {{sociale}}.","verso":"Art. 1er de la Constitution du 4 octobre 1958.","type":"trous","source":"Constitution, art. 1er"},{"id":"seed-fc-l1-souverainete","niveau":"L1","matiere":"Droit constitutionnel","recto":"La souveraineté nationale appartient au {{peuple}} qui l'exerce par ses représentants et par la voie du {{référendum}}.","verso":"Art. 3 de la Constitution.","type":"trous","source":"Constitution, art. 3"},{"id":"seed-fc-l1-mandat-president","niveau":"L1","matiere":"Droit constitutionnel","recto":"Pour combien de temps le Président de la République est-il élu, et combien de mandats peut-il enchaîner ?","verso":"Cinq ans, au suffrage universel direct ; nul ne peut exercer plus de deux mandats consécutifs (art. 6 de la Constitution).","source":"Constitution, art. 6"},{"id":"seed-fc-l1-premier-ministre","niveau":"L1","matiere":"Droit constitutionnel","recto":"Qui nomme le Premier ministre, et comment ses fonctions prennent-elles fin ?","verso":"Le Président de la République le nomme ; il met fin à ses fonctions sur la présentation par le Premier ministre de la démission du Gouvernement (art. 8 de la Constitution).","source":"Constitution, art. 8"},{"id":"seed-fc-l1-dissolution","niveau":"L1","matiere":"Droit constitutionnel","recto":"Le Président peut-il dissoudre l'Assemblée nationale à tout moment ?","verso":"Il peut la dissoudre après avoir consulté le Premier ministre et les présidents des assemblées, mais pas dans l'année qui suit les élections tenues après une dissolution. Les élections ont lieu vingt à quarante jours après la dissolution (art. 12 de la Constitution).","source":"Constitution, art. 12"},{"id":"seed-fc-l1-article-16","niveau":"L1","matiere":"Droit constitutionnel","recto":"À quelles conditions le Président peut-il exercer les pouvoirs exceptionnels de l'article 16 ?","verso":"Il faut une menace grave et immédiate sur les institutions, l'indépendance de la nation, l'intégrité du territoire ou l'exécution des engagements internationaux, et une interruption du fonctionnement régulier des pouvoirs publics constitutionnels. Il consulte le Premier ministre, les présidents des assemblées et le Conseil constitutionnel ; le Parlement se réunit de plein droit.","source":"Constitution, art. 16"},{"id":"seed-fc-l1-49-3","niveau":"L1","matiere":"Droit constitutionnel","recto":"Que permet l'article 49, alinéa 3, de la Constitution ?","verso":"Au Premier ministre, après délibération du conseil des ministres, d'engager la responsabilité du Gouvernement sur le vote d'un projet de loi de finances ou de financement de la sécurité sociale : le texte est considéré comme adopté, sauf si une motion de censure déposée dans les vingt-quatre heures est votée. Hors de ces textes, il ne peut le faire que pour un projet ou une proposition de loi par session.","source":"Constitution, art. 49"},{"id":"seed-fc-l1-conseil-constitutionnel","niveau":"L1","matiere":"Droit constitutionnel","recto":"Comment le Conseil constitutionnel est-il composé ?","verso":"Neuf membres nommés pour neuf ans, mandat non renouvelable, renouvelés par tiers tous les trois ans : trois par le Président de la République, trois par le président de l'Assemblée nationale, trois par le président du Sénat. Les anciens Présidents de la République en sont membres de droit (art. 56 de la Constitution).","source":"Constitution, art. 56"},{"id":"seed-fc-l1-qpc","niveau":"L1-L2","matiere":"Droit constitutionnel","recto":"Qu'est-ce qu'une question prioritaire de constitutionnalité ?","verso":"Au cours d'un procès, une partie soutient qu'une disposition législative porte atteinte aux droits et libertés que la Constitution garantit. Le Conseil constitutionnel en est saisi sur renvoi du Conseil d'État ou de la Cour de cassation (art. 61-1 de la Constitution).","source":"Constitution, art. 61-1 ; fiche d'arrêt n° 2010-1 QPC","arrets":["seed-jp-2010-05-28-consorts-l-pensions-n-2010-1-qpc"]},{"id":"seed-fc-l1-loi-reglement","niveau":"L1","matiere":"Droit constitutionnel","recto":"Comment se partagent le domaine de la loi et celui du règlement ?","verso":"L'article 34 énumère les matières dans lesquelles la loi intervient ; toutes les autres matières ont un caractère réglementaire (art. 37 de la Constitution).","source":"Constitution, art. 34 et 37"},{"id":"seed-fc-l1-preambule","niveau":"L1","matiere":"Droit constitutionnel","recto":"À quels textes le Préambule de la Constitution de 1958 renvoie-t-il ?","verso":"À la Déclaration des droits de l'homme et du citoyen de 1789, au préambule de la Constitution de 1946 et à la Charte de l'environnement de 2004. Le Conseil constitutionnel a reconnu la valeur constitutionnelle du Préambule dans sa décision « Liberté d'association » (1971).","source":"Préambule de la Constitution de 1958 ; fiche d'arrêt n° 71-44 DC","arrets":["seed-jp-1971-07-16-liberte-d-association-n-71-44-dc"]},{"id":"seed-fc-l1-revision","niveau":"L1","matiere":"Droit constitutionnel","recto":"Comment révise-t-on la Constitution selon l'article 89 ?","verso":"L'initiative appartient au Président de la République, sur proposition du Premier ministre, et aux parlementaires. Le texte est voté en termes identiques par les deux assemblées, puis approuvé par référendum ; un projet peut aussi être soumis au Congrès, qui doit l'adopter à la majorité des trois cinquièmes des suffrages exprimés. La forme républicaine du Gouvernement ne peut pas être révisée.","source":"Constitution, art. 89"},{"id":"seed-fc-l1-deux-ordres","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quels sont les deux ordres de juridiction, et qui tranche leurs conflits de compétence ?","verso":"L'ordre judiciaire, avec la Cour de cassation à son sommet, et l'ordre administratif, avec le Conseil d'État. Le Tribunal des conflits tranche les conflits de compétence entre les deux.","source":"Code de l'organisation judiciaire, art. L. 411-1 ; Code de justice administrative, art. L. 111-1 ; loi du 24 mai 1872 relative au Tribunal des conflits"},{"id":"seed-fc-l1-nom-peuple","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Les juridictions judiciaires rendent leurs décisions au {{nom du peuple français}}.","verso":"Art. L. 111-1 du Code de l'organisation judiciaire.","type":"trous","source":"Code de l'organisation judiciaire, art. L. 111-1"},{"id":"seed-fc-l1-tribunal-judiciaire","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quelle est la juridiction civile de droit commun en première instance ?","verso":"Le tribunal judiciaire : il connaît de toutes les affaires civiles et commerciales que la loi n'attribue pas à une autre juridiction (art. L. 211-3 COJ). Il a remplacé le tribunal de grande instance et le tribunal d'instance le 1er janvier 2020.","source":"Code de l'organisation judiciaire, art. L. 211-3"},{"id":"seed-fc-l1-cour-appel","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quel est le rôle de la cour d'appel ?","verso":"Elle rejuge les décisions rendues en premier ressort, civiles et pénales, et statue souverainement sur le fond des affaires, en fait comme en droit (art. L. 311-1 COJ).","source":"Code de l'organisation judiciaire, art. L. 311-1"},{"id":"seed-fc-l1-cassation-fond","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"La Cour de cassation juge-t-elle les faits ?","verso":"Non : elle statue sur les pourvois contre les décisions rendues en dernier ressort et ne connaît pas du fond des affaires, sauf disposition législative contraire (art. L. 411-2 COJ). Elle contrôle l'application du droit.","source":"Code de l'organisation judiciaire, art. L. 411-2"},{"id":"seed-fc-l1-renvoi","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Après une cassation, que devient l'affaire ?","verso":"En principe, elle est renvoyée devant une autre juridiction de même nature, ou devant la même juridiction autrement composée (art. L. 431-4 COJ). La Cour peut casser sans renvoi lorsqu'il n'y a plus rien à juger au fond (art. L. 411-3 COJ).","source":"Code de l'organisation judiciaire, art. L. 431-4 et L. 411-3"},{"id":"seed-fc-l1-ordre-administratif","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quelles juridictions administratives jugent en premier ressort, en appel et en cassation ?","verso":"Les tribunaux administratifs en premier ressort (art. L. 211-1 CJA), les cours administratives d'appel en appel (art. L. 211-2 CJA), le Conseil d'État, juridiction administrative suprême, en cassation (art. L. 111-1 CJA).","source":"Code de justice administrative, art. L. 111-1, L. 211-1 et L. 211-2"},{"id":"seed-fc-l1-juridictions-penales","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quelle juridiction pénale juge les contraventions, les délits, les crimes ?","verso":"Le tribunal de police juge les contraventions (art. 521 CPP), le tribunal correctionnel les délits (art. 381 CPP), la cour d'assises les crimes (art. 231 CPP). Les majeurs accusés d'un crime puni de quinze ou vingt ans de réclusion sont jugés en premier ressort par la cour criminelle départementale (art. 380-16 CPP).","source":"Code de procédure pénale, art. 231, 380-16, 381 et 521"},{"id":"seed-fc-l1-prudhommes","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Qui juge un différend entre un salarié et son employeur, né du contrat de travail ?","verso":"Le conseil de prud'hommes : il cherche d'abord à concilier les parties, puis juge si la conciliation échoue (art. L. 1411-1 C. trav.).","source":"Code du travail, art. L. 1411-1"},{"id":"seed-fc-l1-delai-appel","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quel est le délai de droit commun pour faire appel d'un jugement civil ?","verso":"Un mois en matière contentieuse, quinze jours en matière gracieuse (art. 538 CPC).","source":"Code de procédure civile, art. 538"},{"id":"seed-fc-l1-delai-pourvoi","niveau":"L1","matiere":"Institutions juridictionnelles","recto":"Quel est le délai pour former un pourvoi en cassation en matière civile ?","verso":"Deux mois, sauf disposition contraire (art. 612 CPC).","source":"Code de procédure civile, art. 612"},{"id":"seed-fc-l1-fiche-arret","niveau":"L1","matiere":"Méthode juridique","recto":"Quelles sont les cinq rubriques d'une fiche d'arrêt ?","verso":"Les faits, la procédure, le problème de droit, la solution et la portée.","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l1-probleme-droit","niveau":"L1","matiere":"Méthode juridique","recto":"Comment formuler le problème de droit d'un arrêt ?","verso":"Sous la forme d'une question juridique générale, sans le nom des parties, à laquelle la solution de l'arrêt répond.","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l1-syllogisme","niveau":"L1","matiere":"Méthode juridique","recto":"Qu'est-ce qu'un syllogisme juridique ?","verso":"Un raisonnement en trois temps : la majeure (la règle de droit), la mineure (les faits, qualifiés juridiquement) et la conclusion (la règle appliquée à ces faits).","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l1-qualification","niveau":"L1","matiere":"Méthode juridique","recto":"Qu'est-ce que qualifier juridiquement des faits ?","verso":"Les faire entrer dans une catégorie juridique pour savoir quelle règle s'applique. Le juge doit donner ou restituer leur exacte qualification aux faits et actes litigieux (art. 12 CPC).","source":"Code de procédure civile, art. 12 ; règle de méthode"},{"id":"seed-fc-l1-rejet","niveau":"L1","matiere":"Méthode juridique","recto":"Que signifie un arrêt de rejet de la Cour de cassation ?","verso":"La Cour écarte le pourvoi : elle estime que la décision attaquée a correctement appliqué le droit, et cette décision est maintenue.","source":"Code de l'organisation judiciaire, art. L. 411-2 ; règle de méthode"},{"id":"seed-fc-l1-cassation","niveau":"L1","matiere":"Méthode juridique","recto":"Que signifie un arrêt de cassation ?","verso":"La Cour annule, en tout ou en partie, la décision attaquée pour une erreur de droit, et renvoie en principe l'affaire devant une autre juridiction de même nature (art. L. 431-4 COJ).","source":"Code de l'organisation judiciaire, art. L. 431-4 ; règle de méthode"},{"id":"seed-fc-l1-style-direct","niveau":"L1","matiere":"Méthode juridique","recto":"Comment la Cour de cassation rédige-t-elle ses arrêts depuis le 1er octobre 2019 ?","verso":"En style direct, sans « attendu que », avec des paragraphes numérotés et trois parties : les faits et la procédure, l'examen des moyens, le dispositif. Les arrêts les plus importants reçoivent une « motivation enrichie », plus développée.","source":"Réforme de la rédaction des arrêts de la Cour de cassation, entrée en vigueur le 1er octobre 2019"},{"id":"seed-fc-l1-plan","niveau":"L1","matiere":"Méthode juridique","recto":"Quel plan adopter dans une dissertation ou un commentaire juridique ?","verso":"En principe deux parties et deux sous-parties (I, A et B ; II, A et B), annoncées à la fin de l'introduction et rédigées sous forme de titres.","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l1-principe-espece","niveau":"L1","matiere":"Méthode juridique","recto":"Arrêt de principe ou arrêt d'espèce : quelle différence ?","verso":"L'arrêt de principe pose une règle générale, appelée à s'appliquer au-delà de l'affaire ; l'arrêt d'espèce donne une solution liée aux faits particuliers du litige.","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l1-portee","niveau":"L1","matiere":"Méthode juridique","recto":"Que dit la « portée » dans une fiche d'arrêt ?","verso":"La place de la décision dans le droit : confirme-t-elle, nuance-t-elle ou renverse-t-elle la jurisprudence antérieure, et quelles suites a-t-elle eues (arrêts postérieurs, réforme législative) ?","source":"Règle de méthode d'usage dans les facultés de droit, rédigée par Paraphe"},{"id":"seed-fc-l2-contrat-definition","niveau":"L2","matiere":"Droit des contrats","recto":"Qu'est-ce qu'un contrat, selon le Code civil ?","verso":"Un accord de volontés entre deux ou plusieurs personnes destiné à créer, modifier, transmettre ou éteindre des obligations (art. 1101 C. civ.).","source":"Code civil, art. 1101"},{"id":"seed-fc-l2-force-obligatoire","niveau":"L2","matiere":"Droit des contrats","recto":"Les contrats légalement formés tiennent lieu de {{loi}} à ceux qui les ont faits.","verso":"Art. 1103 du Code civil : la force obligatoire du contrat.","type":"trous","source":"Code civil, art. 1103"},{"id":"seed-fc-l2-bonne-foi","niveau":"L2","matiere":"Droit des contrats","recto":"Les contrats doivent être négociés, formés et exécutés de {{bonne foi}}. Cette disposition est d'{{ordre public}}.","verso":"Art. 1104 du Code civil.","type":"trous","source":"Code civil, art. 1104"},{"id":"seed-fc-l2-validite","niveau":"L2","matiere":"Droit des contrats","recto":"Quelles sont les conditions de validité d'un contrat ?","verso":"Le consentement des parties, leur capacité de contracter, et un contenu licite et certain (art. 1128 C. civ.).","source":"Code civil, art. 1128"},{"id":"seed-fc-l2-formation","niveau":"L2","matiere":"Droit des contrats","recto":"Comment un contrat se forme-t-il ?","verso":"Par la rencontre d'une offre et d'une acceptation par lesquelles les parties manifestent leur volonté de s'engager ; cette volonté peut résulter d'une déclaration ou d'un comportement non équivoque (art. 1113 C. civ.).","source":"Code civil, art. 1113"},{"id":"seed-fc-l2-vices","niveau":"L2","matiere":"Droit des contrats","recto":"Quels sont les vices du consentement, et quand entraînent-ils la nullité ?","verso":"L'erreur, le dol et la violence, lorsqu'ils sont déterminants : sans eux, la partie n'aurait pas contracté, ou à des conditions substantiellement différentes (art. 1130 C. civ.).","source":"Code civil, art. 1130"},{"id":"seed-fc-l2-erreur","niveau":"L2","matiere":"Droit des contrats","recto":"Sur quoi l'erreur doit-elle porter pour entraîner la nullité du contrat ?","verso":"Sur les qualités essentielles de la prestation due ou sur celles du cocontractant ; l'erreur ne doit pas être inexcusable (art. 1132 C. civ.). Exemple : l'authenticité d'une œuvre, dans l'arrêt Poussin.","source":"Code civil, art. 1132 ; fiche d'arrêt Poussin","arrets":["seed-jp-1978-02-22-poussin-1re-civ"]},{"id":"seed-fc-l2-dol","niveau":"L2","matiere":"Droit des contrats","recto":"Qu'est-ce que le dol ?","verso":"Le fait d'obtenir le consentement de l'autre par des manœuvres ou des mensonges, ou par la dissimulation intentionnelle d'une information qu'on sait déterminante pour lui. Ne pas révéler son estimation de la valeur de la prestation n'est pas un dol (art. 1137 C. civ. ; voir déjà l'arrêt Baldus).","source":"Code civil, art. 1137 ; fiche d'arrêt Baldus","arrets":["seed-jp-2000-05-03-baldus-1re-civ"]},{"id":"seed-fc-l2-dependance","niveau":"L2","matiere":"Droit des contrats","recto":"Qu'est-ce que la violence par abus de dépendance ?","verso":"Une partie abuse de l'état de dépendance de son cocontractant pour obtenir de lui un engagement qu'il n'aurait pas souscrit sans cette contrainte, et en tire un avantage manifestement excessif (art. 1143 C. civ.).","source":"Code civil, art. 1143"},{"id":"seed-fc-l2-obligation-essentielle","niveau":"L2","matiere":"Droit des contrats","recto":"Que devient une clause qui prive de sa substance l'obligation essentielle du débiteur ?","verso":"Elle est réputée non écrite (art. 1170 C. civ.). La règle vient de l'arrêt Chronopost (1996), à propos d'une clause limitative de responsabilité.","source":"Code civil, art. 1170 ; fiche d'arrêt Chronopost","arrets":["seed-jp-1996-10-22-chronopost-com"]},{"id":"seed-fc-l2-imprevision","niveau":"L2","matiere":"Droit des contrats","recto":"Que permet l'article 1195 du Code civil en cas de changement de circonstances imprévisible ?","verso":"La partie pour qui l'exécution devient excessivement onéreuse peut demander une renégociation, en continuant d'exécuter. En cas d'échec, les parties peuvent convenir de la résolution ou demander au juge d'adapter le contrat ; à défaut d'accord dans un délai raisonnable, le juge peut réviser le contrat ou y mettre fin. Avant 2016, l'arrêt Canal de Craponne refusait toute révision par le juge.","source":"Code civil, art. 1195 ; fiche d'arrêt Canal de Craponne","arrets":["seed-jp-1876-03-06-canal-de-craponne-civ"]},{"id":"seed-fc-l2-inexecution","niveau":"L2","matiere":"Droit des contrats","recto":"De quelles sanctions dispose le créancier d'une obligation inexécutée ?","verso":"Refuser ou suspendre l'exécution de sa propre obligation, poursuivre l'exécution forcée en nature, obtenir une réduction du prix, provoquer la résolution du contrat, demander réparation. Celles qui sont compatibles se cumulent (art. 1217 C. civ.).","source":"Code civil, art. 1217"},{"id":"seed-fc-l2-1240","niveau":"L2","matiere":"Responsabilité civile","recto":"Tout fait quelconque de l'homme, qui cause à autrui un dommage, oblige celui par la {{faute}} duquel il est arrivé à le {{réparer}}.","verso":"Art. 1240 du Code civil : la responsabilité du fait personnel.","type":"trous","source":"Code civil, art. 1240"},{"id":"seed-fc-l2-1241","niveau":"L2","matiere":"Responsabilité civile","recto":"Faut-il une faute intentionnelle pour engager sa responsabilité ?","verso":"Non : chacun est responsable du dommage causé non seulement par son fait, mais aussi par sa négligence ou son imprudence (art. 1241 C. civ.).","source":"Code civil, art. 1241"},{"id":"seed-fc-l2-trois-conditions","niveau":"L2","matiere":"Responsabilité civile","recto":"Quelles sont les trois conditions de la responsabilité pour faute ?","verso":"Une faute, un dommage, et un lien de causalité entre les deux (art. 1240 C. civ.).","source":"Code civil, art. 1240 ; règle de méthode"},{"id":"seed-fc-l2-fait-des-choses","niveau":"L2","matiere":"Responsabilité civile","recto":"D'où vient le principe général de responsabilité du fait des choses ?","verso":"De l'article 1242, alinéa 1er, du Code civil (ancien art. 1384, al. 1er), lu par la jurisprudence comme un principe général : arrêt Teffaine (1896), puis Jand'heur (1930), qui l'étend à toutes les choses et en fait une présomption de responsabilité.","source":"Code civil, art. 1242 ; fiches d'arrêt Teffaine et Jand'heur","arrets":["seed-jp-1896-06-16-teffaine-civ","seed-jp-1930-02-13-jand-heur-ch-reun"]},{"id":"seed-fc-l2-garde","niveau":"L2","matiere":"Responsabilité civile","recto":"Qui est le gardien d'une chose ?","verso":"Celui qui en a l'usage, la direction et le contrôle (arrêt Franck, 1941). Le propriétaire à qui la chose a été volée n'en est plus le gardien.","source":"Fiche d'arrêt Franck","arrets":["seed-jp-1941-12-02-franck-ch-reun"]},{"id":"seed-fc-l2-exoneration-gardien","niveau":"L2","matiere":"Responsabilité civile","recto":"Comment le gardien d'une chose peut-il s'exonérer ?","verso":"Totalement en prouvant un cas fortuit, une force majeure ou une cause étrangère qui ne lui est pas imputable ; prouver qu'il n'a pas commis de faute ne suffit pas (arrêt Jand'heur). La faute de la victime peut l'exonérer en partie : l'arrêt Desmares (1982) l'avait refusé, il a été abandonné en 1987.","source":"Fiches d'arrêt Jand'heur et Desmares","arrets":["seed-jp-1930-02-13-jand-heur-ch-reun","seed-jp-1982-07-21-desmares-2e-civ"]},{"id":"seed-fc-l2-parents","niveau":"L2","matiere":"Responsabilité civile","recto":"Les parents peuvent-ils échapper à leur responsabilité en prouvant qu'ils n'ont commis aucune faute ?","verso":"Non : ils sont responsables de plein droit du dommage causé par leur enfant mineur (art. 1242 C. civ.) et ne s'exonèrent qu'en prouvant la force majeure ou la faute de la victime (arrêt Bertrand, 1997).","source":"Code civil, art. 1242 ; fiche d'arrêt Bertrand","arrets":["seed-jp-1997-02-19-bertrand-2e-civ"]},{"id":"seed-fc-l2-commettant","niveau":"L2","matiere":"Responsabilité civile","recto":"Le préposé qui cause un dommage dans le cadre de sa mission est-il personnellement responsable envers la victime ?","verso":"Non, s'il n'excède pas les limites de sa mission : seul le commettant répond (art. 1242 C. civ. ; arrêt Costedoat, 2000). Mais le préposé condamné pour une infraction intentionnelle engage sa responsabilité (arrêt Cousin, 2001).","source":"Code civil, art. 1242 ; fiches d'arrêt Costedoat et Cousin","arrets":["seed-jp-2000-02-25-costedoat-ass-plen","seed-jp-2001-12-14-cousin-ass-plen"]},{"id":"seed-fc-l2-blieck","niveau":"L2-L3","matiere":"Responsabilité civile","recto":"Peut-on être responsable du fait d'autrui en dehors des cas énumérés par le Code civil ?","verso":"Oui : avec l'arrêt Blieck (1991), une association qui a accepté d'organiser et de contrôler à titre permanent le mode de vie d'une personne handicapée doit répondre des dommages qu'elle cause.","source":"Fiche d'arrêt Blieck","arrets":["seed-jp-1991-03-29-blieck-ass-plen"]},{"id":"seed-fc-l2-derguini","niveau":"L2","matiere":"Responsabilité civile","recto":"Un très jeune enfant peut-il commettre une faute qui réduit son droit à réparation ?","verso":"Oui : la faute de la victime peut être retenue contre un enfant en bas âge sans qu'il soit capable de discerner la portée de son acte (arrêt Derguini, 1984).","source":"Fiche d'arrêt Derguini","arrets":["seed-jp-1984-05-09-derguini-ass-plen"]},{"id":"seed-fc-l2-voisinage","niveau":"L2","matiere":"Responsabilité civile","recto":"Qui répond d'un trouble anormal de voisinage, et faut-il une faute ?","verso":"Celui qui est à l'origine d'un trouble excédant les inconvénients normaux de voisinage (propriétaire, locataire, occupant, maître d'ouvrage…) en est responsable de plein droit, sans faute (art. 1253 C. civ., depuis 2024 ; principe posé par la jurisprudence auparavant).","source":"Code civil, art. 1253 ; fiche d'arrêt « Troubles anormaux de voisinage »","arrets":["seed-jp-1986-11-19-troubles-anormaux-de-voisinage-2e-civ"]},{"id":"seed-fc-l2-produits","niveau":"L2","matiere":"Responsabilité civile","recto":"Quand un produit est-il défectueux, et qui en répond ?","verso":"Quand il n'offre pas la sécurité à laquelle on peut légitimement s'attendre (art. 1245-3 C. civ.). Le producteur est responsable du dommage causé par ce défaut, qu'il soit ou non lié par un contrat avec la victime (art. 1245 C. civ.).","source":"Code civil, art. 1245 et 1245-3"},{"id":"seed-fc-l2-cadot","niveau":"L2","matiere":"Droit administratif","recto":"Que décide l'arrêt Cadot (1889) ?","verso":"Il abandonne la théorie du « ministre-juge » : le Conseil d'État devient compétent pour connaître directement de toutes les affaires administratives, comme juge de droit commun.","source":"Fiche d'arrêt Cadot","arrets":["seed-jp-1889-12-13-cadot"]},{"id":"seed-fc-l2-delai-rep","niveau":"L2","matiere":"Droit administratif","recto":"Dans quel délai faut-il attaquer une décision administrative devant le juge ?","verso":"Deux mois à partir de la notification ou de la publication de la décision (art. R. 421-1 CJA).","source":"Code de justice administrative, art. R. 421-1"},{"id":"seed-fc-l2-lamotte","niveau":"L2","matiere":"Droit administratif","recto":"Le recours pour excès de pouvoir existe-t-il même sans texte qui le prévoie ?","verso":"Oui : il est ouvert même sans texte contre tout acte administratif ; seule une disposition législative expresse peut l'exclure, et le juge l'interprète strictement (arrêt Dame Lamotte, 1950).","source":"Fiche d'arrêt Dame Lamotte","arrets":["seed-jp-1950-02-17-dame-lamotte-ass"]},{"id":"seed-fc-l2-refere-suspension","niveau":"L2","matiere":"Droit administratif","recto":"À quelles conditions le juge des référés peut-il suspendre une décision administrative ?","verso":"Une requête en annulation ou en réformation doit être déposée ; il faut l'urgence et un moyen propre à créer un doute sérieux sur la légalité de la décision (art. L. 521-1 CJA).","source":"Code de justice administrative, art. L. 521-1"},{"id":"seed-fc-l2-refere-liberte","niveau":"L2","matiere":"Droit administratif","recto":"Qu'est-ce que le référé-liberté ?","verso":"En cas d'urgence, le juge des référés ordonne toute mesure nécessaire à la sauvegarde d'une liberté fondamentale à laquelle l'administration a porté une atteinte grave et manifestement illégale ; il se prononce en quarante-huit heures (art. L. 521-2 CJA).","source":"Code de justice administrative, art. L. 521-2"},{"id":"seed-fc-l2-silence","niveau":"L2","matiere":"Droit administratif","recto":"Que vaut, en principe, le silence gardé deux mois par l'administration sur une demande ?","verso":"Une décision d'acceptation (art. L. 231-1 du Code des relations entre le public et l'administration). Des textes prévoient des exceptions où le silence vaut rejet.","source":"Code des relations entre le public et l'administration, art. L. 231-1"},{"id":"seed-fc-l2-retrait","niveau":"L2","matiere":"Droit administratif","recto":"L'administration peut-elle retirer une décision créatrice de droits ?","verso":"Seulement si elle est illégale, et dans les quatre mois qui suivent la décision (art. L. 242-1 CRPA). La règle vient de l'arrêt Ternon (2001).","source":"Code des relations entre le public et l'administration, art. L. 242-1 ; fiche d'arrêt Ternon","arrets":["seed-jp-2001-10-26-ternon-ass"]},{"id":"seed-fc-l2-labonne","niveau":"L2-L3","matiere":"Droit administratif","recto":"Que reconnaît l'arrêt Labonne (1919) ?","verso":"Le chef de l'État tient de ses attributions constitutionnelles le pouvoir de réglementer la police à l'échelle nationale, sans habilitation législative. Sous la Ve République, ce pouvoir de police générale appartient au Premier ministre (art. 21 de la Constitution).","source":"Fiche d'arrêt Labonne ; Constitution, art. 21","arrets":["seed-jp-1919-08-08-labonne"]},{"id":"seed-fc-l2-lutetia","niveau":"L2-L3","matiere":"Droit administratif","recto":"Un maire peut-il interdire dans sa commune un film qui a reçu le visa national ?","verso":"Oui, en vertu de ses pouvoirs de police et en raison de circonstances locales exceptionnelles, si la projection risque d'entraîner des troubles sérieux ou d'être préjudiciable à l'ordre public (arrêt Société des films Lutétia, 1959).","source":"Fiche d'arrêt Société des films Lutétia","arrets":["seed-jp-1959-12-18-societe-des-films-lutetia-sect"]},{"id":"seed-fc-l2-couiteas","niveau":"L2","matiere":"Droit administratif","recto":"L'État peut-il devoir indemniser sans avoir commis de faute ?","verso":"Oui : quand une décision légale fait peser sur une personne une charge qu'elle n'a pas à supporter, la rupture de l'égalité devant les charges publiques est indemnisée (arrêt Couitéas, 1923, refus légal du concours de la force publique).","source":"Fiche d'arrêt Couitéas","arrets":["seed-jp-1923-11-30-couiteas"]},{"id":"seed-fc-l2-imprevision-admin","niveau":"L2-L3","matiere":"Droit administratif","recto":"Qu'est-ce que la théorie de l'imprévision en droit administratif ?","verso":"Quand un événement imprévisible, extérieur aux parties, bouleverse l'économie d'un contrat administratif, le cocontractant doit poursuivre le service et peut obtenir une indemnité d'imprévision (arrêt Compagnie générale d'éclairage de Bordeaux, 1916).","source":"Fiche d'arrêt Compagnie générale d'éclairage de Bordeaux","arrets":["seed-jp-1916-03-30-compagnie-generale-d-eclairage-de-bordea"]},{"id":"seed-fc-l2-cumul","niveau":"L2","matiere":"Droit administratif","recto":"Faute personnelle de l'agent et faute de service peuvent-elles se cumuler ?","verso":"Oui : la faute personnelle n'exclut pas la faute de service. La victime peut agir contre l'administration, qui dispose ensuite d'une action récursoire contre l'agent (arrêts Anguet, 1911, et Époux Lemonnier, 1918).","source":"Fiches d'arrêt Anguet et Époux Lemonnier","arrets":["seed-jp-1911-02-03-anguet","seed-jp-1918-07-26-epoux-lemonnier"]},{"id":"seed-fc-l2-classification","niveau":"L2","matiere":"Droit pénal général","recto":"Les infractions pénales sont classées, suivant leur gravité, en {{crimes}}, {{délits}} et {{contraventions}}.","verso":"Art. 111-1 du Code pénal.","type":"trous","source":"Code pénal, art. 111-1"},{"id":"seed-fc-l2-legalite","niveau":"L2","matiere":"Droit pénal général","recto":"Que dit le principe de légalité des délits et des peines ?","verso":"Nul ne peut être puni pour un crime ou un délit dont les éléments ne sont pas définis par la loi, ni pour une contravention que le règlement ne définit pas ; la peine doit aussi être prévue par la loi ou le règlement (art. 111-3 C. pén.).","source":"Code pénal, art. 111-3"},{"id":"seed-fc-l2-interpretation","niveau":"L2","matiere":"Droit pénal général","recto":"La loi pénale est d'interprétation {{stricte}}.","verso":"Art. 111-4 du Code pénal. Exemple : l'homicide involontaire n'a pas été étendu à l'enfant à naître (Ass. plén., 2001).","type":"trous","source":"Code pénal, art. 111-4 ; fiche d'arrêt « Homicide involontaire du fœtus »","arrets":["seed-jp-2001-06-29-homicide-involontaire-du-ftus-ass-plen"]},{"id":"seed-fc-l2-retroactivite","niveau":"L2","matiere":"Droit pénal général","recto":"Une loi pénale nouvelle plus douce s'applique-t-elle à des faits commis avant elle ?","verso":"Oui, si ces faits n'ont pas encore donné lieu à une condamnation passée en force de chose jugée : c'est la rétroactivité de la loi pénale plus douce. Une loi plus sévère, elle, ne s'applique qu'aux faits postérieurs (art. 112-1 C. pén.).","source":"Code pénal, art. 112-1"},{"id":"seed-fc-l2-propre-fait","niveau":"L2","matiere":"Droit pénal général","recto":"Nul n'est responsable pénalement que de son {{propre fait}}.","verso":"Art. 121-1 du Code pénal.","type":"trous","source":"Code pénal, art. 121-1"},{"id":"seed-fc-l2-intention","niveau":"L2","matiere":"Droit pénal général","recto":"Un délit peut-il exister sans intention de le commettre ?","verso":"En principe non (art. 121-3 C. pén.), sauf lorsque la loi le prévoit : mise en danger délibérée de la personne d'autrui, ou faute d'imprudence, de négligence ou de manquement à une obligation de prudence ou de sécurité.","source":"Code pénal, art. 121-3"},{"id":"seed-fc-l2-tentative","niveau":"L2","matiere":"Droit pénal général","recto":"Quand y a-t-il tentative punissable ?","verso":"Lorsqu'elle est manifestée par un commencement d'exécution et n'a été suspendue ou n'a manqué son effet qu'en raison de circonstances indépendantes de la volonté de son auteur (art. 121-5 C. pén.).","source":"Code pénal, art. 121-5"},{"id":"seed-fc-l2-complicite","niveau":"L2","matiere":"Droit pénal général","recto":"Quelles sont les formes de la complicité ?","verso":"L'aide ou l'assistance apportée sciemment à la préparation ou à la consommation d'un crime ou d'un délit, et la provocation (don, promesse, menace, ordre, abus d'autorité ou de pouvoir) ou les instructions données pour le commettre (art. 121-7 C. pén.). Sans fait principal punissable, pas de complicité (arrêt Lacour, 1962).","source":"Code pénal, art. 121-7 ; fiche d'arrêt Lacour","arrets":["seed-jp-1962-10-25-lacour-crim"]},{"id":"seed-fc-l2-trouble-psychique","niveau":"L2","matiere":"Droit pénal général","recto":"Abolition ou altération du discernement : quelle différence pour la responsabilité pénale ?","verso":"Un trouble psychique ou neuropsychique qui a aboli le discernement rend la personne pénalement irresponsable ; s'il l'a seulement altéré, elle reste punissable, mais la juridiction en tient compte pour fixer la peine (art. 122-1 C. pén.).","source":"Code pénal, art. 122-1"},{"id":"seed-fc-l2-legitime-defense","niveau":"L2","matiere":"Droit pénal général","recto":"Quelles sont les conditions de la légitime défense d'une personne ?","verso":"Une atteinte injustifiée envers soi ou autrui, un acte de défense accompli dans le même temps et commandé par la nécessité, et des moyens qui ne soient pas disproportionnés à la gravité de l'atteinte (art. 122-5 C. pén.).","source":"Code pénal, art. 122-5"},{"id":"seed-fc-l2-necessite","niveau":"L2","matiere":"Droit pénal général","recto":"Qu'est-ce que l'état de nécessité ?","verso":"N'est pas responsable la personne qui, face à un danger actuel ou imminent pour elle-même, autrui ou un bien, accomplit un acte nécessaire à leur sauvegarde, sauf disproportion avec la gravité de la menace (art. 122-7 C. pén.). Il trouve son origine dans le jugement Ménard (1898).","source":"Code pénal, art. 122-7 ; fiche d'arrêt Ménard","arrets":["seed-jp-1898-03-04-menard-tribunal-de-chateau-thierry"]},{"id":"seed-fc-l3-meubles-immeubles","niveau":"L3","matiere":"Droit des biens","recto":"Tous les biens sont {{meubles}} ou {{immeubles}}.","verso":"Art. 516 du Code civil : la summa divisio des biens.","type":"trous","source":"Code civil, art. 516"},{"id":"seed-fc-l3-propriete","niveau":"L2-L3","matiere":"Droit des biens","recto":"Comment le Code civil définit-il la propriété ?","verso":"Le droit de jouir et disposer des choses de la manière la plus absolue, pourvu qu'on n'en fasse pas un usage prohibé par les lois ou les règlements (art. 544 C. civ.).","source":"Code civil, art. 544"},{"id":"seed-fc-l3-expropriation","niveau":"L3","matiere":"Droit des biens","recto":"Peut-on être contraint de céder sa propriété ?","verso":"Seulement pour cause d'utilité publique, et moyennant une juste et préalable indemnité (art. 545 C. civ.).","source":"Code civil, art. 545"},{"id":"seed-fc-l3-usufruit","niveau":"L3","matiere":"Droit des biens","recto":"Qu'est-ce que l'usufruit ?","verso":"Le droit de jouir des choses dont un autre a la propriété, comme le propriétaire lui-même, mais à charge d'en conserver la substance (art. 578 C. civ.).","source":"Code civil, art. 578"},{"id":"seed-fc-l3-indivision","niveau":"L3","matiere":"Droit des biens","recto":"Nul ne peut être contraint à demeurer dans l'{{indivision}} et le {{partage}} peut toujours être provoqué, à moins qu'il n'y ait été sursis par jugement ou convention.","verso":"Art. 815 du Code civil.","type":"trous","source":"Code civil, art. 815"},{"id":"seed-fc-l3-possession-qualites","niveau":"L3","matiere":"Droit des biens","recto":"Quelles qualités la possession doit-elle avoir pour permettre de prescrire ?","verso":"Elle doit être continue et non interrompue, paisible, publique, non équivoque, et à titre de propriétaire (art. 2261 C. civ.).","source":"Code civil, art. 2261"},{"id":"seed-fc-l3-usucapion","niveau":"L3","matiere":"Droit des biens","recto":"Au bout de combien de temps peut-on acquérir un immeuble par la possession ?","verso":"Trente ans ; dix ans seulement pour celui qui acquiert de bonne foi et par juste titre (art. 2272 C. civ.).","source":"Code civil, art. 2272"},{"id":"seed-fc-l3-meubles-possession","niveau":"L3","matiere":"Droit des biens","recto":"En fait de meubles, la {{possession}} vaut {{titre}}.","verso":"Art. 2276 du Code civil ; le propriétaire d'une chose perdue ou volée peut la revendiquer pendant trois ans.","type":"trous","source":"Code civil, art. 2276"},{"id":"seed-fc-l3-empietement","niveau":"L2-L3","matiere":"Droit des biens","recto":"Le propriétaire victime d'un empiètement, même minime, peut-il obtenir la démolition ?","verso":"Oui : la défense du droit de propriété contre un empiètement ne dégénère pas en abus ; il obtient la suppression de l'ouvrage, sans que le juge apprécie la gravité de l'atteinte (Cass. 3e civ., 1990).","source":"Fiche d'arrêt « Empiètement et démolition »","arrets":["seed-jp-1990-06-07-empietement-et-demolition-3e-civ"]},{"id":"seed-fc-l3-image-biens","niveau":"L2-L3","matiere":"Droit des biens","recto":"Le propriétaire d'une chose a-t-il un droit exclusif sur son image ?","verso":"Non : il peut seulement s'opposer à l'utilisation de cette image par un tiers si elle lui cause un trouble anormal (arrêt Hôtel de Girancourt, 2004).","source":"Fiche d'arrêt Hôtel de Girancourt","arrets":["seed-jp-2004-05-07-hotel-de-girancourt-ass-plen"]},{"id":"seed-fc-l3-dispositif","niveau":"L3","matiere":"Procédure civile","recto":"Le juge doit se prononcer sur tout ce qui est {{demandé}} et seulement sur ce qui est {{demandé}}.","verso":"Art. 5 du Code de procédure civile : le juge ne statue ni infra ni ultra petita.","type":"trous","source":"Code de procédure civile, art. 5"},{"id":"seed-fc-l3-faits","niveau":"L3","matiere":"Procédure civile","recto":"À qui revient-il d'alléguer les faits, puis de les prouver ?","verso":"Aux parties : elles ont la charge d'alléguer les faits propres à fonder leurs prétentions (art. 6 CPC) et de prouver ceux qui sont nécessaires au succès de leur prétention (art. 9 CPC).","source":"Code de procédure civile, art. 6 et 9"},{"id":"seed-fc-l3-audition","niveau":"L3","matiere":"Procédure civile","recto":"Nulle partie ne peut être jugée sans avoir été {{entendue}} ou {{appelée}}.","verso":"Art. 14 du Code de procédure civile.","type":"trous","source":"Code de procédure civile, art. 14"},{"id":"seed-fc-l3-contradictoire","niveau":"L3","matiere":"Procédure civile","recto":"Le juge peut-il fonder sa décision sur un moyen de droit qu'il relève d'office ?","verso":"Seulement après avoir invité les parties à présenter leurs observations : il doit observer lui-même le principe de la contradiction (art. 16 CPC).","source":"Code de procédure civile, art. 16"},{"id":"seed-fc-l3-interet","niveau":"L3","matiere":"Procédure civile","recto":"Qui peut agir en justice ?","verso":"Tous ceux qui ont un intérêt légitime au succès ou au rejet d'une prétention, sauf lorsque la loi réserve l'action à certaines personnes qualifiées (art. 31 CPC).","source":"Code de procédure civile, art. 31"},{"id":"seed-fc-l3-exceptions","niveau":"L3","matiere":"Procédure civile","recto":"Qu'est-ce qu'une exception de procédure, et quand faut-il la soulever ?","verso":"Un moyen qui tend à faire déclarer la procédure irrégulière ou éteinte, ou à en suspendre le cours (art. 73 CPC). Elle doit être soulevée, à peine d'irrecevabilité, avant toute défense au fond ou fin de non-recevoir, et en même temps que les autres exceptions (art. 74 CPC).","source":"Code de procédure civile, art. 73 et 74"},{"id":"seed-fc-l3-fin-non-recevoir","niveau":"L3","matiere":"Procédure civile","recto":"Qu'est-ce qu'une fin de non-recevoir ? Donnez des exemples.","verso":"Un moyen qui tend à faire déclarer l'adversaire irrecevable, sans examen au fond, pour défaut de droit d'agir : défaut de qualité ou d'intérêt, prescription, délai préfix, chose jugée (art. 122 CPC).","source":"Code de procédure civile, art. 122"},{"id":"seed-fc-l3-refere","niveau":"L3","matiere":"Procédure civile","recto":"Que peut ordonner le juge des référés en cas d'urgence ?","verso":"Toutes les mesures qui ne se heurtent à aucune contestation sérieuse ou que justifie l'existence d'un différend (art. 834 CPC).","source":"Code de procédure civile, art. 834"},{"id":"seed-fc-l3-chose-jugee","niveau":"L3","matiere":"Procédure civile","recto":"À quelles conditions l'autorité de la chose jugée s'oppose-t-elle à une nouvelle demande ?","verso":"Il faut la même chose demandée, la même cause et les mêmes parties, agissant en la même qualité (art. 1355 C. civ.).","source":"Code civil, art. 1355"},{"id":"seed-fc-l3-cesareo","niveau":"L3","matiere":"Procédure civile","recto":"Que décide l'arrêt Cesareo (2006) sur les moyens d'une demande ?","verso":"Le demandeur doit présenter dès la première instance tous les moyens qu'il estime de nature à fonder sa demande ; il ne peut pas en invoquer un nouveau dans une instance postérieure (concentration des moyens).","source":"Fiche d'arrêt Cesareo","arrets":["seed-jp-2006-07-07-cesareo-ass-plen"]},{"id":"seed-fc-l3-effet-direct","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Que pose l'arrêt Van Gend en Loos (1963) ?","verso":"L'effet direct : le droit communautaire crée des droits et obligations pour les particuliers, que les juridictions nationales doivent sauvegarder ; la Communauté constitue un nouvel ordre juridique.","source":"Fiche d'arrêt Van Gend en Loos","arrets":["seed-jp-1963-02-05-van-gend-en-loos"]},{"id":"seed-fc-l3-primaute","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Que consacre l'arrêt Costa c. ENEL (1964) ?","verso":"La primauté du droit communautaire : issu d'une source autonome, il ne peut se voir opposer un texte interne quel qu'il soit, antérieur ou postérieur.","source":"Fiche d'arrêt Costa c. ENEL","arrets":["seed-jp-1964-07-15-costa-c-enel"]},{"id":"seed-fc-l3-simmenthal","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Que doit faire le juge national face à une loi contraire au droit de l'Union, selon l'arrêt Simmenthal (1978) ?","verso":"La laisser inappliquée de lui-même, même si elle est postérieure, sans demander ni attendre son élimination préalable.","source":"Fiche d'arrêt Simmenthal","arrets":["seed-jp-1978-03-09-simmenthal"]},{"id":"seed-fc-l3-renvoi-prejudiciel","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Qu'est-ce que le renvoi préjudiciel ?","verso":"La Cour de justice de l'Union européenne statue à titre préjudiciel sur l'interprétation des traités et sur la validité et l'interprétation des actes de l'Union ; une juridiction nationale peut la saisir si elle l'estime nécessaire pour rendre son jugement (art. 267 TFUE).","source":"TFUE, art. 267"},{"id":"seed-fc-l3-restrictions","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Les restrictions quantitatives à l'{{importation}} ainsi que toutes {{mesures d'effet équivalent}}, sont interdites entre les États membres.","verso":"Art. 34 du TFUE.","type":"trous","source":"TFUE, art. 34"},{"id":"seed-fc-l3-dassonville","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Qu'est-ce qu'une mesure d'effet équivalent, selon l'arrêt Dassonville (1974) ?","verso":"Toute réglementation commerciale des États membres susceptible d'entraver directement ou indirectement, actuellement ou potentiellement, le commerce entre États membres.","source":"Fiche d'arrêt Dassonville","arrets":["seed-jp-1974-07-11-dassonville"]},{"id":"seed-fc-l3-cassis","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Que pose l'arrêt Cassis de Dijon (1979) ?","verso":"La reconnaissance mutuelle : un produit légalement fabriqué et commercialisé dans un État membre doit pouvoir circuler dans les autres, sauf exigences impératives (santé, loyauté des transactions, protection du consommateur) proportionnées.","source":"Fiche d'arrêt Cassis de Dijon","arrets":["seed-jp-1979-02-20-cassis-de-dijon-rewe-zentral"]},{"id":"seed-fc-l3-francovich","niveau":"L3-M1","matiere":"Droit de l'Union européenne","recto":"Un particulier peut-il obtenir réparation d'un État qui viole le droit de l'Union ?","verso":"Oui : la responsabilité de l'État pour les dommages causés par les violations qui lui sont imputables est inhérente au traité ; pour une directive non transposée, elle doit conférer des droits identifiables et il faut un lien de causalité (arrêt Francovich, 1991).","source":"Fiche d'arrêt Francovich et Bonifaci","arrets":["seed-jp-1991-11-19-francovich-et-bonifaci"]},{"id":"seed-fc-l3-marshall","niveau":"L3","matiere":"Droit de l'Union européenne","recto":"Une directive peut-elle être invoquée contre un particulier ?","verso":"Non : par elle-même, elle ne crée pas d'obligations à la charge d'un particulier (pas d'effet direct horizontal) ; elle peut être invoquée contre l'État, même en sa qualité d'employeur (arrêt Marshall, 1986).","source":"Fiche d'arrêt Marshall (n° 1)","arrets":["seed-jp-1986-02-26-marshall-n-1"]},{"id":"seed-fc-l3-mariage","niveau":"L3","matiere":"Droit de la famille","recto":"Le mariage est contracté par deux personnes de sexe {{différent}} ou de {{même sexe}}.","verso":"Art. 143 du Code civil, depuis la loi du 17 mai 2013.","type":"trous","source":"Code civil, art. 143"},{"id":"seed-fc-l3-age-mariage","niveau":"L3","matiere":"Droit de la famille","recto":"À partir de quel âge peut-on se marier ?","verso":"Dix-huit ans révolus (art. 144 C. civ.).","source":"Code civil, art. 144"},{"id":"seed-fc-l3-devoirs-epoux","niveau":"L3","matiere":"Droit de la famille","recto":"Les époux se doivent mutuellement {{respect}}, {{fidélité}}, {{secours}}, {{assistance}}.","verso":"Art. 212 du Code civil.","type":"trous","source":"Code civil, art. 212"},{"id":"seed-fc-l3-cas-divorce","niveau":"L3","matiere":"Droit de la famille","recto":"Quels sont les cas de divorce ?","verso":"Le consentement mutuel par acte sous signature privée contresigné par avocats et déposé chez un notaire ; et, devant le juge, le consentement mutuel (cas particulier), l'acceptation du principe de la rupture, l'altération définitive du lien conjugal et la faute (art. 229 C. civ.).","source":"Code civil, art. 229"},{"id":"seed-fc-l3-divorce-avocats","niveau":"L3","matiere":"Droit de la famille","recto":"Comment se fait un divorce par consentement mutuel sans juge ?","verso":"Les époux, assistés chacun par un avocat, constatent leur accord sur la rupture et ses effets dans une convention contresignée par leurs avocats, puis déposée au rang des minutes d'un notaire, qui contrôle les exigences de forme (art. 229-1 C. civ.).","source":"Code civil, art. 229-1"},{"id":"seed-fc-l3-maternite","niveau":"L3","matiere":"Droit de la famille","recto":"Comment la filiation s'établit-elle à l'égard de la mère ?","verso":"Par la désignation de la mère dans l'acte de naissance de l'enfant (art. 311-25 C. civ.).","source":"Code civil, art. 311-25"},{"id":"seed-fc-l3-paternite","niveau":"L3","matiere":"Droit de la famille","recto":"L'enfant conçu ou né pendant le {{mariage}} a pour père le {{mari}}.","verso":"Art. 312 du Code civil : la présomption de paternité.","type":"trous","source":"Code civil, art. 312"},{"id":"seed-fc-l3-autorite-parentale","niveau":"L3","matiere":"Droit de la famille","recto":"Qu'est-ce que l'autorité parentale ?","verso":"Un ensemble de droits et de devoirs ayant pour finalité l'intérêt de l'enfant ; elle appartient aux parents jusqu'à sa majorité ou son émancipation, pour le protéger dans sa sécurité, sa santé, sa vie privée et sa moralité, assurer son éducation et permettre son développement ; elle s'exerce sans violences physiques ou psychologiques (art. 371-1 C. civ.).","source":"Code civil, art. 371-1"},{"id":"seed-fc-l3-pacs","niveau":"L2-L3","matiere":"Droit de la famille","recto":"Qu'est-ce qu'un pacte civil de solidarité ?","verso":"Un contrat conclu par deux personnes physiques majeures, de sexe différent ou de même sexe, pour organiser leur vie commune (art. 515-1 C. civ.).","source":"Code civil, art. 515-1"},{"id":"seed-fc-m1-droit-de-gage-general","niveau":"L3-M1","matiere":"Droit des sûretés","recto":"Quiconque s'est obligé personnellement, est tenu de remplir son engagement sur tous ses biens {{mobiliers et immobiliers}}, présents et à venir.","verso":"Art. 2284 du Code civil : le droit de gage général des créanciers.","type":"trous","source":"Code civil, art. 2284"},{"id":"seed-fc-m1-gage-commun","niveau":"L3-M1","matiere":"Droit des sûretés","recto":"Comment se répartit le prix des biens du débiteur entre ses créanciers ?","verso":"Les biens du débiteur sont le gage commun de ses créanciers ; le prix se distribue entre eux par contribution, sauf causes légitimes de préférence (art. 2285 C. civ.).","source":"Code civil, art. 2285"},{"id":"seed-fc-m1-surete-reelle","niveau":"M1","matiere":"Droit des sûretés","recto":"Qu'est-ce qu'une sûreté réelle ?","verso":"L'affectation d'un bien ou d'un ensemble de biens, présents ou futurs, au paiement préférentiel ou exclusif du créancier (art. 2323 C. civ.).","source":"Code civil, art. 2323"},{"id":"seed-fc-m1-cautionnement","niveau":"L3-M1","matiere":"Droit des sûretés","recto":"Le cautionnement est le contrat par lequel une caution s'oblige envers le créancier à payer la dette du débiteur en cas de {{défaillance}} de celui-ci.","verso":"Art. 2288 du Code civil, depuis la réforme du 15 septembre 2021 ; il peut être souscrit même à l'insu du débiteur.","type":"trous","source":"Code civil, art. 2288"},{"id":"seed-fc-m1-mention-caution","niveau":"M1","matiere":"Droit des sûretés","recto":"Quelle formalité la caution personne physique doit-elle accomplir, et à quelle sanction ?","verso":"Apposer elle-même la mention qu'elle s'engage à payer au créancier ce que lui doit le débiteur en cas de défaillance, dans la limite d'un montant écrit en toutes lettres et en chiffres, à peine de nullité de son engagement ; en cas de différence, la somme en lettres l'emporte (art. 2297 C. civ.).","source":"Code civil, art. 2297"},{"id":"seed-fc-m1-disproportion","niveau":"M1","matiere":"Droit des sûretés","recto":"Que devient le cautionnement manifestement disproportionné souscrit par une personne physique envers un créancier professionnel ?","verso":"Il est réduit au montant à hauteur duquel la caution pouvait s'engager à la date de sa conclusion (art. 2300 C. civ., depuis 2021). Avant la loi, l'arrêt Macron (1997) sanctionnait déjà la banque par la responsabilité.","source":"Code civil, art. 2300 ; fiche d'arrêt Macron","arrets":["seed-jp-1997-06-17-macron-com"]},{"id":"seed-fc-m1-exceptions-caution","niveau":"M1","matiere":"Droit des sûretés","recto":"La caution peut-elle opposer au créancier les exceptions du débiteur ?","verso":"Oui, toutes les exceptions, personnelles ou inhérentes à la dette ; mais pas les mesures légales ou judiciaires dont le débiteur bénéficie du fait de sa défaillance, sauf disposition spéciale contraire (art. 2298 C. civ.).","source":"Code civil, art. 2298"},{"id":"seed-fc-m1-information-annuelle","niveau":"M1","matiere":"Droit des sûretés","recto":"Que doit faire chaque année le créancier professionnel envers la caution personne physique ?","verso":"Lui faire connaître, avant le 31 mars et à ses frais, le montant de la dette restant due au 31 décembre précédent, sous peine de déchéance des intérêts et pénalités échus depuis la précédente information (art. 2302 C. civ.).","source":"Code civil, art. 2302"},{"id":"seed-fc-m1-gage","niveau":"M1","matiere":"Droit des sûretés","recto":"Qu'est-ce que le gage ?","verso":"Une convention par laquelle le constituant accorde à un créancier le droit de se faire payer par préférence à ses autres créanciers sur un bien mobilier ou un ensemble de biens mobiliers corporels, présents ou futurs (art. 2333 C. civ.).","source":"Code civil, art. 2333"},{"id":"seed-fc-m1-attribution-gage","niveau":"M1","matiere":"Droit des sûretés","recto":"Faute de paiement, quelles voies s'ouvrent au créancier gagiste ?","verso":"Poursuivre la vente du bien gagé (art. 2346 C. civ.) ou faire ordonner en justice que le bien lui demeure en paiement, en reversant l'excédent de valeur au constituant (art. 2347 C. civ.).","source":"Code civil, art. 2346 et 2347"},{"id":"seed-fc-m1-conciliation","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Quel débiteur peut demander une conciliation ?","verso":"Celui qui exerce une activité commerciale ou artisanale, éprouve une difficulté juridique, économique ou financière, avérée ou prévisible, et n'est pas en cessation des paiements depuis plus de quarante-cinq jours (art. L. 611-4 C. com.).","source":"Code de commerce, art. L. 611-4"},{"id":"seed-fc-m1-sauvegarde","niveau":"M1","matiere":"Entreprises en difficulté","recto":"À quelle condition une procédure de sauvegarde peut-elle être ouverte ?","verso":"Sur demande du débiteur qui, sans être en cessation des paiements, justifie de difficultés qu'il n'est pas en mesure de surmonter (art. L. 620-1 C. com.).","source":"Code de commerce, art. L. 620-1"},{"id":"seed-fc-m1-cessation-paiements","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Qu'est-ce que la cessation des paiements ?","verso":"L'impossibilité de faire face au passif exigible avec l'actif disponible ; le débiteur dont les réserves de crédit ou les moratoires permettent d'y faire face n'est pas en cessation des paiements (art. L. 631-1 C. com.).","source":"Code de commerce, art. L. 631-1"},{"id":"seed-fc-m1-delai-45-jours","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Dans quel délai le débiteur doit-il demander l'ouverture d'un redressement judiciaire ?","verso":"Au plus tard dans les quarante-cinq jours qui suivent la cessation des paiements, s'il n'a pas demandé dans ce délai l'ouverture d'une conciliation (art. L. 631-4 C. com.).","source":"Code de commerce, art. L. 631-4"},{"id":"seed-fc-m1-liquidation","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Quand ouvre-t-on une liquidation judiciaire ?","verso":"Lorsque le débiteur est en cessation des paiements et que son redressement est manifestement impossible ; elle met fin à l'activité ou réalise le patrimoine du débiteur (art. L. 640-1 C. com.).","source":"Code de commerce, art. L. 640-1"},{"id":"seed-fc-m1-interdiction-payer","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Le débiteur peut-il payer ses créanciers antérieurs après le jugement d'ouverture ?","verso":"Non : le jugement emporte de plein droit interdiction de payer toute créance née antérieurement, sauf paiement par compensation de créances connexes ; les créances alimentaires échappent à cette interdiction (art. L. 622-7 C. com.).","source":"Code de commerce, art. L. 622-7"},{"id":"seed-fc-m1-arret-poursuites","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Quel est l'effet du jugement d'ouverture sur les actions des créanciers antérieurs ?","verso":"Il interrompt ou interdit les actions tendant à la condamnation du débiteur au paiement d'une somme d'argent ou à la résolution d'un contrat pour défaut de paiement, et arrête ou interdit les procédures d'exécution (art. L. 622-21 C. com.).","source":"Code de commerce, art. L. 622-21"},{"id":"seed-fc-m1-declaration-creances","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Dans quel délai les créanciers doivent-ils déclarer leurs créances, et à qui ?","verso":"Au mandataire judiciaire (art. L. 622-24 C. com.), dans les deux mois de la publication du jugement d'ouverture au Bulletin officiel des annonces civiles et commerciales, délai augmenté de deux mois pour les créanciers établis hors de France métropolitaine (art. R. 622-24 C. com.).","source":"Code de commerce, art. L. 622-24 et R. 622-24"},{"id":"seed-fc-m1-periode-observation","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Que doit décider le tribunal dans les deux mois du jugement ouvrant un redressement judiciaire ?","verso":"S'il ordonne la poursuite de la période d'observation, ce qu'il fait lorsque le débiteur dispose de capacités de financement suffisantes (art. L. 631-15 C. com.).","source":"Code de commerce, art. L. 631-15"},{"id":"seed-fc-m1-duree-plan","niveau":"M1","matiere":"Entreprises en difficulté","recto":"Quelle est la durée maximale d'un plan de sauvegarde ?","verso":"Dix ans, fixés par le tribunal ; quinze ans pour un débiteur exerçant une activité agricole (art. L. 626-12 C. com.).","source":"Code de commerce, art. L. 626-12"},{"id":"seed-fc-m1-delai-recours","niveau":"L3-M1","matiere":"Contentieux administratif","recto":"La juridiction ne peut être saisie que par voie de recours formé contre une décision, et ce, dans les {{deux mois}} à partir de la notification ou de la publication de la décision attaquée.","verso":"Art. R. 421-1 du Code de justice administrative.","type":"trous","source":"Code de justice administrative, art. R. 421-1"},{"id":"seed-fc-m1-mention-voies","niveau":"M1","matiere":"Contentieux administratif","recto":"À quelle condition le délai de recours est-il opposable ?","verso":"Il faut que la notification de la décision mentionne ce délai et les voies de recours (art. R. 421-5 CJA).","source":"Code de justice administrative, art. R. 421-5"},{"id":"seed-fc-m1-czabaj","niveau":"M1","matiere":"Contentieux administratif","recto":"Sans mention des voies et délais, une décision peut-elle être contestée indéfiniment ?","verso":"Non : la sécurité juridique impose d'agir dans un délai raisonnable, en principe un an à compter de la connaissance de la décision (arrêt Czabaj, 2016).","source":"Fiche d'arrêt Czabaj ; Code de justice administrative, art. R. 421-5","arrets":["seed-jp-2016-07-13-czabaj-ass"]},{"id":"seed-fc-m1-refere-provisoire","niveau":"M1","matiere":"Contentieux administratif","recto":"Le juge des référés statue par des mesures qui présentent un caractère {{provisoire}}.","verso":"Art. L. 511-1 du Code de justice administrative : il n'est pas saisi du principal et se prononce dans les meilleurs délais.","type":"trous","source":"Code de justice administrative, art. L. 511-1"},{"id":"seed-fc-m1-refere-suspension","niveau":"M1","matiere":"Contentieux administratif","recto":"Quelles sont les conditions du référé-suspension ?","verso":"Une requête en annulation ou en réformation contre la décision, l'urgence, et un moyen propre à créer, en l'état de l'instruction, un doute sérieux quant à sa légalité (art. L. 521-1 CJA).","source":"Code de justice administrative, art. L. 521-1"},{"id":"seed-fc-m1-refere-liberte","niveau":"M1","matiere":"Contentieux administratif","recto":"Que permet le référé-liberté, et en combien de temps le juge statue-t-il ?","verso":"Ordonner toutes mesures nécessaires à la sauvegarde d'une liberté fondamentale à laquelle l'administration a porté une atteinte grave et manifestement illégale, en cas d'urgence ; le juge se prononce dans les quarante-huit heures (art. L. 521-2 CJA).","source":"Code de justice administrative, art. L. 521-2"},{"id":"seed-fc-m1-refere-mesures-utiles","niveau":"M1","matiere":"Contentieux administratif","recto":"Qu'est-ce que le référé « mesures utiles » ?","verso":"En cas d'urgence, sur simple requête recevable même sans décision préalable, le juge peut ordonner toutes autres mesures utiles, sans faire obstacle à l'exécution d'une décision administrative (art. L. 521-3 CJA).","source":"Code de justice administrative, art. L. 521-3"},{"id":"seed-fc-m1-injonction","niveau":"M1","matiere":"Contentieux administratif","recto":"Le juge administratif peut-il enjoindre à l'administration de prendre une mesure ?","verso":"Oui : lorsque sa décision implique nécessairement une mesure d'exécution dans un sens déterminé, il la prescrit, le cas échéant avec un délai, sur conclusions ou d'office (art. L. 911-1 CJA).","source":"Code de justice administrative, art. L. 911-1"},{"id":"seed-fc-m1-danthony","niveau":"M1","matiere":"Contentieux administratif","recto":"Un vice de procédure entraîne-t-il toujours l'annulation de la décision ?","verso":"Non : seulement s'il a pu exercer une influence sur le sens de la décision ou s'il a privé les intéressés d'une garantie (arrêt Danthony, 2011).","source":"Fiche d'arrêt Danthony","arrets":["seed-jp-2011-12-23-danthony-ass"]},{"id":"seed-fc-m1-tarn-et-garonne","niveau":"M1","matiere":"Contentieux administratif","recto":"Un tiers peut-il contester la validité d'un contrat administratif ?","verso":"Oui : tout tiers susceptible d'être lésé de façon suffisamment directe et certaine par sa passation ou ses clauses peut former un recours de plein contentieux, dans les deux mois suivant les mesures de publicité appropriées (arrêt Département de Tarn-et-Garonne, 2014).","source":"Fiche d'arrêt Département de Tarn-et-Garonne","arrets":["seed-jp-2014-04-04-departement-de-tarn-et-garonne-ass"]},{"id":"seed-fc-m2-bail-duree","niveau":"M1-M2","matiere":"Baux commerciaux","recto":"La durée du contrat de location ne peut être inférieure à {{neuf ans}}.","verso":"Art. L. 145-4 du Code de commerce ; le preneur peut donner congé à l'expiration de chaque période triennale, au moins six mois à l'avance.","type":"trous","source":"Code de commerce, art. L. 145-4"},{"id":"seed-fc-m2-bail-derogatoire","niveau":"M1-M2","matiere":"Baux commerciaux","recto":"Peut-on échapper au statut des baux commerciaux ?","verso":"Oui, à l'entrée dans les lieux, par un bail dérogatoire dont la durée totale, baux successifs compris, ne dépasse pas trois ans ; si le preneur reste et est laissé en possession plus d'un mois après l'échéance, un bail soumis au statut prend naissance (art. L. 145-5 C. com.).","source":"Code de commerce, art. L. 145-5"},{"id":"seed-fc-m2-exploitation-effective","niveau":"M2","matiere":"Baux commerciaux","recto":"Qui peut invoquer le droit au renouvellement ?","verso":"Le propriétaire du fonds exploité dans les lieux ; sauf motifs légitimes, le fonds doit avoir été effectivement exploité au cours des trois années précédant l'expiration du bail ou de sa prolongation (art. L. 145-8 C. com.).","source":"Code de commerce, art. L. 145-8"},{"id":"seed-fc-m2-conge","niveau":"M1-M2","matiere":"Baux commerciaux","recto":"Comment prend fin un bail commercial ?","verso":"Seulement par un congé donné six mois à l'avance ou par une demande de renouvellement ; à défaut, le bail écrit se prolonge tacitement, et le congé doit alors être donné six mois à l'avance pour le dernier jour du trimestre civil (art. L. 145-9 C. com.).","source":"Code de commerce, art. L. 145-9"},{"id":"seed-fc-m2-demande-renouvellement","niveau":"M2","matiere":"Baux commerciaux","recto":"Quand le locataire peut-il demander le renouvellement, et sous quelle forme ?","verso":"Dans les six mois qui précèdent l'expiration du bail ou à tout moment au cours de sa prolongation, par acte extrajudiciaire ou par lettre recommandée avec demande d'avis de réception (art. L. 145-10 C. com.).","source":"Code de commerce, art. L. 145-10"},{"id":"seed-fc-m2-indemnite-eviction","niveau":"M1-M2","matiere":"Baux commerciaux","recto":"Le bailleur peut-il refuser le renouvellement ?","verso":"Oui, mais il doit en principe payer au locataire évincé une indemnité d'éviction égale au préjudice causé, comprenant notamment la valeur marchande du fonds et les frais de déménagement et de réinstallation (art. L. 145-14 C. com.).","source":"Code de commerce, art. L. 145-14"},{"id":"seed-fc-m2-motif-grave","niveau":"M2","matiere":"Baux commerciaux","recto":"Quand le bailleur peut-il refuser le renouvellement sans indemnité pour un manquement du locataire ?","verso":"S'il justifie d'un motif grave et légitime ; pour l'inexécution d'une obligation ou l'arrêt injustifié de l'exploitation, l'infraction doit s'être poursuivie plus d'un mois après une mise en demeure délivrée par acte extrajudiciaire, à peine de nullité (art. L. 145-17 C. com.).","source":"Code de commerce, art. L. 145-17"},{"id":"seed-fc-m2-clause-resolutoire","niveau":"M2","matiere":"Baux commerciaux","recto":"Quand la clause résolutoire d'un bail commercial produit-elle effet ?","verso":"Un mois après un commandement demeuré infructueux, qui doit mentionner ce délai à peine de nullité ; le juge peut accorder des délais et suspendre ses effets (art. L. 145-41 C. com.).","source":"Code de commerce, art. L. 145-41"},{"id":"seed-fc-m2-droit-preference","niveau":"M2","matiere":"Baux commerciaux","recto":"Le locataire commercial est-il prioritaire si le bailleur vend le local ?","verso":"Oui : la notification du projet de vente, qui doit indiquer le prix et les conditions à peine de nullité, vaut offre de vente ; le locataire dispose d'un mois pour se prononcer (art. L. 145-46-1 C. com.).","source":"Code de commerce, art. L. 145-46-1"},{"id":"seed-fc-m2-prescription-baux","niveau":"M1-M2","matiere":"Baux commerciaux","recto":"Toutes les actions exercées en vertu du présent chapitre se prescrivent par {{deux ans}}.","verso":"Art. L. 145-60 du Code de commerce : la prescription biennale du statut des baux commerciaux.","type":"trous","source":"Code de commerce, art. L. 145-60"},{"id":"seed-fc-m2-consommateur","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"Qui est consommateur au sens du Code de la consommation ?","verso":"Toute personne physique qui agit à des fins qui n'entrent pas dans le cadre de son activité commerciale, industrielle, artisanale, libérale ou agricole (article liminaire C. consom.).","source":"Code de la consommation, article liminaire"},{"id":"seed-fc-m2-clause-abusive","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"Qu'est-ce qu'une clause abusive ?","verso":"Dans un contrat entre professionnel et consommateur, une clause qui crée, au détriment du consommateur, un déséquilibre significatif entre les droits et obligations des parties (art. L. 212-1 C. consom.) ; la règle vaut aussi pour les non-professionnels (art. L. 212-2).","source":"Code de la consommation, art. L. 212-1 et L. 212-2"},{"id":"seed-fc-m2-sanction-clause","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"Les clauses abusives sont réputées {{non écrites}}.","verso":"Art. L. 241-1 du Code de la consommation : le contrat subsiste sans elles s'il le peut.","type":"trous","source":"Code de la consommation, art. L. 241-1"},{"id":"seed-fc-m2-office-juge","niveau":"M2","matiere":"Droit de la consommation","recto":"Le juge peut-il relever d'office le caractère abusif d'une clause ?","verso":"Il le doit : il écarte d'office, après avoir recueilli les observations des parties, une clause dont le caractère abusif ressort des éléments du débat (art. R. 632-1 C. consom.), comme l'avait admis la Cour de justice dans l'arrêt Océano (2000).","source":"Code de la consommation, art. R. 632-1 ; fiche d'arrêt Océano Grupo Editorial","arrets":["seed-jp-2000-06-27-oceano-grupo-editorial-cjce"]},{"id":"seed-fc-m2-retractation","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"De quel délai le consommateur dispose-t-il pour se rétracter d'un contrat conclu à distance ou hors établissement ?","verso":"Quatorze jours, sans motif ; ils courent de la conclusion du contrat pour une prestation de services, de la réception du bien pour une vente (art. L. 221-18 C. consom.).","source":"Code de la consommation, art. L. 221-18"},{"id":"seed-fc-m2-retractation-prolongee","niveau":"M2","matiere":"Droit de la consommation","recto":"Que se passe-t-il si le professionnel n'a pas informé le consommateur de son droit de rétractation ?","verso":"Le délai est prolongé de douze mois à compter de l'expiration du délai initial ; si l'information est donnée pendant cette prolongation, le délai expire quatorze jours après sa réception (art. L. 221-20 C. consom.).","source":"Code de la consommation, art. L. 221-20"},{"id":"seed-fc-m2-retractation-credit","niveau":"M2","matiere":"Droit de la consommation","recto":"Peut-on se rétracter d'un crédit à la consommation ?","verso":"Oui, sans motif, dans un délai de quatorze jours calendaires révolus à compter de l'acceptation de l'offre (art. L. 312-19 C. consom.).","source":"Code de la consommation, art. L. 312-19"},{"id":"seed-fc-m2-garantie-conformite","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"Pendant combien de temps le vendeur répond-il des défauts de conformité ?","verso":"De ceux qui existent à la délivrance et apparaissent dans les deux ans qui suivent (art. L. 217-3 C. consom.) ; ils sont présumés exister à la délivrance s'ils apparaissent dans les vingt-quatre mois, douze mois pour un bien d'occasion (art. L. 217-7).","source":"Code de la consommation, art. L. 217-3 et L. 217-7"},{"id":"seed-fc-m2-prescription-conso","niveau":"M1-M2","matiere":"Droit de la consommation","recto":"L'action des professionnels, pour les biens ou les services qu'ils fournissent aux consommateurs, se prescrit par {{deux ans}}.","verso":"Art. L. 218-2 du Code de la consommation.","type":"trous","source":"Code de la consommation, art. L. 218-2"},{"id":"seed-fc-m2-retractation-exclusions","niveau":"M2","matiere":"Droit de la consommation","recto":"Le droit de rétractation existe-t-il pour tous les contrats à distance ?","verso":"Non : l'article L. 221-28 en exclut une liste, dont les services pleinement exécutés avant la fin du délai avec l'accord exprès du consommateur, et les biens dont le prix dépend des fluctuations du marché financier.","source":"Code de la consommation, art. L. 221-28"},{"id":"seed-fc-m2-execution-forcee","niveau":"M2","matiere":"Voies d'exécution","recto":"À quelles conditions un créancier peut-il poursuivre l'exécution forcée ?","verso":"Il doit être muni d'un titre exécutoire constatant une créance liquide et exigible (art. L. 111-2 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 111-2"},{"id":"seed-fc-m2-dix-ans","niveau":"M2","matiere":"Voies d'exécution","recto":"Pendant combien de temps un jugement peut-il être exécuté ?","verso":"Dix ans, sauf si l'action en recouvrement de la créance se prescrit par un délai plus long ; la règle vaut pour les titres des 1° à 3° de l'art. L. 111-3 (décisions de justice, titres étrangers et sentences déclarés exécutoires, procès-verbaux de conciliation) (art. L. 111-4 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 111-4"},{"id":"seed-fc-m2-proportionnalite","niveau":"M2","matiere":"Voies d'exécution","recto":"Le créancier choisit-il librement la mesure d'exécution ?","verso":"Oui, mais l'exécution ne peut excéder ce qui se révèle nécessaire pour obtenir le paiement (art. L. 111-7 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 111-7"},{"id":"seed-fc-m2-astreinte","niveau":"M1-M2","matiere":"Voies d'exécution","recto":"Tout juge peut, même d'office, ordonner une {{astreinte}} pour assurer l'exécution de sa décision.","verso":"Art. L. 131-1 du Code des procédures civiles d'exécution ; le juge de l'exécution peut aussi en assortir la décision d'un autre juge.","type":"trous","source":"Code des procédures civiles d'exécution, art. L. 131-1"},{"id":"seed-fc-m2-astreinte-provisoire","niveau":"M2","matiere":"Voies d'exécution","recto":"Une astreinte est-elle provisoire ou définitive ?","verso":"Provisoire, sauf si le juge a précisé son caractère définitif ; une astreinte définitive ne peut être ordonnée qu'après une astreinte provisoire et pour une durée déterminée. Elle est indépendante des dommages-intérêts (art. L. 131-2 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 131-2"},{"id":"seed-fc-m2-saisie-attribution","niveau":"M2","matiere":"Voies d'exécution","recto":"Quel est l'effet de la saisie-attribution ?","verso":"L'acte de saisie emporte attribution immédiate au saisissant de la créance saisie, à concurrence des sommes pour lesquelles elle est pratiquée ; une saisie ultérieure ou l'ouverture d'une procédure collective ne la remet pas en cause (art. L. 211-2 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 211-2"},{"id":"seed-fc-m2-saisie-vente","niveau":"M2","matiere":"Voies d'exécution","recto":"Que faut-il pour saisir et vendre les meubles corporels du débiteur ?","verso":"Un titre exécutoire constatant une créance liquide et exigible et la signification préalable d'un commandement ; l'autorisation du juge de l'exécution est requise si les biens sont détenus par un tiers dans ses locaux d'habitation (art. L. 221-1 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 221-1"},{"id":"seed-fc-m2-treve-hivernale","niveau":"M2","matiere":"Voies d'exécution","recto":"Peut-on expulser un occupant en hiver ?","verso":"Non : il est sursis à toute expulsion non exécutée du 1er novembre au 31 mars, sauf relogement assuré dans des conditions suffisantes ou introduction dans le domicile d'autrui par manœuvres, menaces, voies de fait ou contrainte (art. L. 412-6 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 412-6"},{"id":"seed-fc-m2-mesure-conservatoire","niveau":"M2","matiere":"Voies d'exécution","recto":"À quelles conditions peut-on obtenir une mesure conservatoire ?","verso":"Une créance qui paraît fondée en son principe et des circonstances susceptibles d'en menacer le recouvrement ; le juge autorise la mesure sans commandement préalable, sous forme de saisie conservatoire ou de sûreté judiciaire (art. L. 511-1 CPCE).","source":"Code des procédures civiles d'exécution, art. L. 511-1"},{"id":"seed-fc-m2-jex","niveau":"M2","matiere":"Voies d'exécution","recto":"De quoi connaît le juge de l'exécution ?","verso":"De manière exclusive, des difficultés relatives aux titres exécutoires et des contestations nées de l'exécution forcée, même sur le fond du droit ; il autorise aussi les mesures conservatoires et connaît de la saisie immobilière (art. L. 213-6 COJ).","source":"Code de l'organisation judiciaire, art. L. 213-6"}];
